-- Per-player Skills, Ratings and Development goals (ADR-0015). Deliberately separate lists from
-- the Line ones: a Player skill is never a Line Skill, and neither list sees the other's rows.
-- Fixed UUIDs by kind: 6=player_skill, 7=player_development_goal.

create table player_skill (
    id uuid primary key,
    name varchar(100) not null,
    color varchar(7) not null,
    deleted_at timestamptz
);

create table player_development_goal (
    id uuid primary key,
    name varchar(100) not null,
    color varchar(7) not null,
    deleted_at timestamptz
);

create table player_skill_rating (
    player_id uuid not null references player (id),
    player_skill_id uuid not null references player_skill (id),
    rating int not null check (rating between 0 and 100),
    primary key (player_id, player_skill_id)
);

create table player_player_development_goal (
    player_id uuid not null references player (id),
    player_development_goal_id uuid not null references player_development_goal (id),
    primary key (player_id, player_development_goal_id)
);

